package cn.finance.review;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.security.core.Authentication;
import static cn.finance.review.Db.*;
import static cn.finance.review.ApiError.require;
@Service
public class PublicationService {
 final Db db;final Access access;final VersionDiff diffs;
 public PublicationService(Db db,Access access,VersionDiff diffs){this.db=db;this.access=access;this.diffs=diffs;}
 public Map<String,Object> publication(String product){return db.one("SELECT * FROM product_publication WHERE product_id=:p",Map.of("p",product));}
 public Map<String,Object> release(String id){return id==null||id.isBlank()?new LinkedHashMap<>():db.one("SELECT * FROM product_release WHERE id=:id",Map.of("id",id));}
 public String cloneDataset(String product,String chain,String old){
  String id=id();Map<String,Object> d=old==null||old.isBlank()?map("id",id,"productId",product,"chain",chain,"state","DRAFT","rawCoverage","UNKNOWN","riskCoverage","UNKNOWN","sourceAsOf","","rawAsOf","","riskAsOf","","assetId",null,"baseDatasetId",null,"createdAt",now()):new LinkedHashMap<>(db.one("SELECT * FROM review_dataset WHERE id=:id",Map.of("id",old)));
  d.put("id",id);d.put("state","DRAFT");d.put("baseDatasetId",old);d.put("createdAt",now());db.insert("review_dataset",d);
  if(old==null||old.isBlank())return id;
  Map<String,String> sourceIds=new HashMap<>();for(var r:db.rows("SELECT * FROM "+Fields.sourceTable(chain)+" WHERE dataset_id=:id",Map.of("id",old))){String before=str(r,"id"),newId=id();sourceIds.put(before,newId);r.put("id",newId);r.put("datasetId",id);r.put("baseRowId",str(r,"baseRowId").isBlank()?before:r.get("baseRowId"));r.put("recordVersion",1);db.insert(Fields.sourceTable(chain),r);}
  for(var f:findings(old,chain)){String before=str(f,"id");f.put("id",id());f.put("datasetId",id);f.put("baseFindingId",str(f,"baseFindingId").isBlank()?before:f.get("baseFindingId"));f.put("currentSourceId",sourceIds.get(str(f,"currentSourceId")));f.put("recordVersion",1);insertFinding(f,chain);}
  return id;
 }
 public List<Map<String,Object>> findings(String dataset,String chain){return db.rows("SELECT f.*, d.* FROM risk_finding f JOIN "+Fields.detailTable(chain)+" d ON f.id=d.finding_id WHERE f.dataset_id=:id",Map.of("id",dataset));}
 public void insertFinding(Map<String,Object> r,String chain){var head=Fields.select(r,List.of("id","datasetId","chain","ruleCode","checkName","risk","workflow","violation","advice","evidence","confidence","auditedSourceId","currentSourceId","linkStatus","linkMethod","linkReason","linkDetail","linkCandidates","baseFindingId","sourceAssetId","sourceSheet","sourceRow","recordVersion"));db.insert("risk_finding",head);var detail=Fields.select(r,Fields.detailColumns(chain));detail.put("findingId",r.get("id"));db.insert(Fields.detailTable(chain),detail);}
 public Map<String,Object> createDraft(Authentication a,String product,List<String> chains){access.product(a,product,"write");return db.transaction(()->newDraft(product,publication(product),access.actor(a),chains));}
 Map<String,Object> newDraft(String product,Map<String,Object> base,String actor,List<String> chains){Map<String,Object> old=release(str(base,"releaseId"));Map<String,Object> draft=map("id",id(),"productId",product,"baseReleaseId",base.get("releaseId"),"baseRevision",base.get("revision"),"userDatasetId",null,"matrixDatasetId",null,"state","VALIDATED","createdBy",actor,"createdAt",now(),"revision",1);for(String chain:chains){require(List.of("user","matrix").contains(chain),422,"CHAIN","链路无效");draft.put(chain+"DatasetId",cloneDataset(product,chain,str(old,chain+"DatasetId")));}db.insert("review_draft",draft);return draft;}
 public Map<String,Object> draft(Authentication a,String id,boolean lock){var d=db.one("SELECT * FROM review_draft WHERE id=:id"+(lock?" FOR UPDATE":""),Map.of("id",id));access.product(a,str(d,"productId"),"write");d.put("stale",!Objects.equals(publication(str(d,"productId")).get("releaseId"),d.get("baseReleaseId")));return d;}
 public static int version(String match){require(match!=null&&!match.isBlank(),428,"VERSION_REQUIRED","请携带 If-Match 版本条件");try{return Integer.parseInt(match.replace("\"",""));}catch(Exception e){throw new ApiError(422,"VERSION","版本格式无效");}}
 public void editable(Map<String,Object> d){require(List.of("DRAFT","VALIDATED").contains(str(d,"state")),409,"DRAFT_STATE","草稿已发布或已放弃");require(!Boolean.TRUE.equals(d.get("stale")),412,"BASE_CHANGED","产品当前版本已变化，请基于新版重新预览");}
 public Map<String,Object> preview(Authentication a,String id){var d=draft(a,id,false);List<Map<String,Object>> changes=new ArrayList<>();Map<String,Object> old=release(str(d,"baseReleaseId"));for(String chain:List.of("user","matrix")){String ds=str(d,chain+"DatasetId");if(ds.isBlank())continue;var meta=db.one("SELECT * FROM review_dataset WHERE id=:id",Map.of("id",ds));String before=str(old,chain+"DatasetId");changes.add(map("chain",chain,"datasetId",ds,"oldRaw",before.isBlank()?0:db.count("SELECT COUNT(*) FROM "+Fields.sourceTable(chain)+" WHERE dataset_id=:id",Map.of("id",before)),"newRaw",db.count("SELECT COUNT(*) FROM "+Fields.sourceTable(chain)+" WHERE dataset_id=:id",Map.of("id",ds)),"oldRisk",before.isBlank()?0:db.count("SELECT COUNT(*) FROM risk_finding WHERE dataset_id=:id",Map.of("id",before)),"newRisk",db.count("SELECT COUNT(*) FROM risk_finding WHERE dataset_id=:id",Map.of("id",ds)),"unlinked",db.count("SELECT COUNT(*) FROM risk_finding WHERE dataset_id=:id AND link_status NOT IN ('LINKED','LINKED_WEAK')",Map.of("id",ds)),"recheck",db.count("SELECT COUNT(*) FROM risk_finding WHERE dataset_id=:id AND workflow='待复核'",Map.of("id",ds)),"rawCoverage",meta.get("rawCoverage"),"riskCoverage",meta.get("riskCoverage"),"rawAsOf",meta.get("rawAsOf"),"riskAsOf",meta.get("riskAsOf")));}d.put("changes",changes);String user=str(d,"userDatasetId").isBlank()?str(old,"userDatasetId"):str(d,"userDatasetId"),matrix=str(d,"matrixDatasetId").isBlank()?str(old,"matrixDatasetId"):str(d,"matrixDatasetId");d.put("difference",diffs.compare(str(d,"productId"),str(old,"userDatasetId"),str(old,"matrixDatasetId"),user,matrix));d.put("linkDiagnostics",db.rows("SELECT link_status,COALESCE(link_reason,'LEGACY_NOT_DIAGNOSED') AS link_reason,COUNT(*) AS count FROM risk_finding WHERE dataset_id IN (:ids) GROUP BY link_status,link_reason ORDER BY link_status,link_reason",map("ids",List.of(user,matrix))));return d;}
 public Map<String,Object> publish(Authentication a,String id,String match,String requestKey,Map<String,Object> body){var original=draft(a,id,false);String product=str(original,"productId");access.product(a,product,"publish");String reason=str(body,"reason").trim();require(!reason.isBlank()&&reason.length()<=2000,422,"REASON","请填写有效发布原因");require(requestKey!=null&&requestKey.length()>=8&&requestKey.length()<=100,422,"IDEMPOTENCY_KEY","发布必须携带幂等键");String digest=Fields.hash(id+"|"+match+"|"+db.encode(new TreeMap<>(body)));return db.transaction(()->{
  var pub=db.one("SELECT * FROM product_publication WHERE product_id=:p FOR UPDATE",Map.of("p",product));var oldRequest=db.optional("SELECT * FROM publish_request WHERE actor=:a AND product_id=:p AND request_key=:k",Map.of("a",access.actor(a),"p",product,"k",requestKey));if(oldRequest!=null){require(digest.equals(str(oldRequest,"requestDigest")),409,"IDEMPOTENCY_CONFLICT","同一幂等键对应了不同的发布内容");return release(str(oldRequest,"releaseId"));}
  var d=draft(a,id,true);editable(d);require(num(d,"revision")==version(match),412,"DRAFT_CHANGED","草稿已变化，请重新预览");require(Objects.equals(pub.get("releaseId"),d.get("baseReleaseId")),412,"BASE_CHANGED","产品当前版本已变化，请重新预览");
  for(String chain:List.of("user","matrix")){String ds=str(d,chain+"DatasetId");if(ds.isBlank())continue;long count=db.count("SELECT COUNT(*) FROM risk_finding WHERE dataset_id=:id",Map.of("id",ds));var meta=db.one("SELECT * FROM review_dataset WHERE id=:id",Map.of("id",ds));if(count==0&&str(meta,"riskCoverage").equals("FULL"))require(Boolean.TRUE.equals(body.get("allowEmpty")),422,"EMPTY_CONFIRMATION","完整空清单必须明确确认替换为0条");}
  var previous=release(str(pub,"releaseId"));String user=str(d,"userDatasetId").isBlank()?str(previous,"userDatasetId"):str(d,"userDatasetId");String matrix=str(d,"matrixDatasetId").isBlank()?str(previous,"matrixDatasetId"):str(d,"matrixDatasetId");var r=createRelease(product,user,matrix,pub,a,reason);db.update("UPDATE review_draft SET state='PUBLISHED',revision=revision+1 WHERE id=:id",Map.of("id",id));db.insert("publish_request",map("actor",access.actor(a),"productId",product,"requestKey",requestKey,"requestDigest",digest,"releaseId",r.get("id")));return r;
 });}
 private Map<String,Object> createRelease(String product,String user,String matrix,Map<String,Object> pub,Authentication a,String reason){Map<String,Object> r=map("id",id(),"productId",product,"userDatasetId",user==null||user.isBlank()?null:user,"matrixDatasetId",matrix==null||matrix.isBlank()?null:matrix,"baseReleaseId",pub.get("releaseId"),"publishedBy",access.actor(a),"publishedAt",now(),"reason",reason,"releaseNumber",num(pub,"revision")+1);db.insert("product_release",r);db.update("UPDATE product_publication SET release_id=:id,revision=revision+1 WHERE product_id=:p",Map.of("id",r.get("id"),"p",product));for(String ds:List.of(Objects.requireNonNullElse(user,""),Objects.requireNonNullElse(matrix,"")))if(!ds.isBlank())db.update("UPDATE review_dataset SET state='PUBLISHED' WHERE id=:id",Map.of("id",ds));db.event(product,access.actor(a),"PUBLISH",str(r,"id"),pub,r,reason);return r;}
 public Map<String,Object> rollback(Authentication a,String product,String target,String match,String reason){access.product(a,product,"publish");require(!reason.isBlank(),422,"REASON","回退必须填写原因");return db.transaction(()->{var p=db.one("SELECT * FROM product_publication WHERE product_id=:p FOR UPDATE",Map.of("p",product));require(num(p,"revision")==version(match),412,"BASE_CHANGED","产品版本已变化");var old=release(target);require(product.equals(str(old,"productId")),404,"NOT_FOUND","目标版本不属于该产品");return createRelease(product,str(old,"userDatasetId"),str(old,"matrixDatasetId"),p,a,"回退："+reason);});}
 public Map<String,Object> compare(Authentication a,String product,String from,String to){access.product(a,product,"read");var current=to==null||to.isBlank()?release(str(publication(product),"releaseId")):release(to);require(!current.isEmpty()&&product.equals(str(current,"productId")),404,"NOT_FOUND","目标版本不属于所选产品");var previous=release(from==null||from.isBlank()?str(current,"baseReleaseId"):from);require(previous.isEmpty()||product.equals(str(previous,"productId")),404,"NOT_FOUND","对比版本不属于所选产品");var result=diffs.compare(product,str(previous,"userDatasetId"),str(previous,"matrixDatasetId"),str(current,"userDatasetId"),str(current,"matrixDatasetId"));result.put("fromReleaseId",previous.get("id"));result.put("toReleaseId",current.get("id"));return result;}
 public List<Map<String,Object>> history(Authentication a,String product){access.product(a,product,"read");return db.rows("SELECT id,release_number,published_by,published_at,reason FROM product_release WHERE product_id=:p ORDER BY release_number DESC",Map.of("p",product));}
 public void discard(Authentication a,String id,String match){db.transaction(()->{var d=draft(a,id,true);require(!str(d,"state").equals("PUBLISHED"),409,"DRAFT_STATE","已发布草稿不能放弃");require(num(d,"revision")==version(match),412,"DRAFT_CHANGED","草稿版本已变化");db.update("UPDATE review_draft SET state='DISCARDED', revision=revision+1 WHERE id=:id",Map.of("id",id));db.event(str(d,"productId"),access.actor(a),"DISCARD_DRAFT",id,null,null,"放弃草稿");return null;});}
}
